import{HostDocument}from'./host-document';
export async function verifyRetouchAudit(){
 const image=document.createElement('canvas');image.width=image.height=4100;const c=image.getContext('2d')!;c.fillStyle='white';c.fillRect(0,0,4100,4100);c.fillStyle='black';c.fillRect(0,0,32,32);
 const layer={name:'Audit',opacity:1,isVisible:true,hasClipping:false,mixModeStr:'source-over' as const,image};
 const full=new HostDocument({projectId:'retouch-full',width:4100,height:4100,layers:[layer]});try{const original=full.contentIdentity();let committed=false;try{full.beginRetouch([2010,2010,1],{tool:'clone',size:5000,hardness:1,opacity:1,strength:1,offset:{x:-2000,y:-2000},merged:false});full.endRetouch();committed=true;}catch(e){if(!(e instanceof Error)||!e.message.includes('撤销'))throw e;}if(committed)full.undo();if(full.contentIdentity()!==original)throw Error('Oversized stamp lost immediate undo or failed rollback');}finally{full.destroy();}
 const d=new HostDocument({projectId:'retouch-diagonal',width:4100,height:4100,layers:[layer]});
 try{d.beginRetouch([100,100,1],{tool:'clone',size:10,hardness:1,opacity:1,strength:1,offset:{x:-90,y:-90},merged:false});d.moveRetouch([4090,4090,1]);d.endRetouch();d.undo();if(d.canvas.getLayer(0).context.getImageData(100,100,1,1).data[0]!==255)throw Error('Diagonal clone lost single-stroke undo');d.redo();if(d.canvas.getLayer(0).context.getImageData(100,100,1,1).data[0]!==0)throw Error('Diagonal clone redo failed');}finally{d.destroy();image.width=image.height=0;}
 const edge=document.createElement('canvas');edge.width=32;edge.height=16;const ec=edge.getContext('2d')!;ec.fillStyle='white';ec.fillRect(0,0,32,16);ec.fillStyle='black';ec.fillRect(0,0,16,16);
 const weak=new HostDocument({projectId:'blur-weak',width:32,height:16,layers:[{...layer,image:edge}]}),strong=new HostDocument({projectId:'blur-strong',width:32,height:16,layers:[{...layer,image:edge}]});
 const options={tool:'blur' as const,size:16,hardness:1,opacity:1,strength:1,offset:{x:0,y:0},merged:false};
 const read=(doc:HostDocument,x:number)=>doc.canvas.getLayer(0).context.getImageData(x,8,1,1).data;
 try{for(const [doc,strength]of [[weak,0.25],[strong,1]]as const){doc.select([[[[16,0],[32,0],[32,16],[16,16],[16,0]]]],'replace');doc.beginRetouch([16,8,1],{...options,strength});doc.moveRetouch([20,8,1]);doc.endRetouch();if(read(doc,12)[0]!==0||read(doc,30)[0]!==255||read(doc,16)[3]!==255)throw Error('Blur escaped selection or changed alpha');}if(!(read(weak,16)[0]!>read(strong,16)[0]!&&read(weak,16)[0]!<255))throw Error('Blur strength ineffective');strong.undo();if(read(strong,16)[0]!==255)throw Error('Blur undo failed');let rejected=false;try{strong.beginRetouch([0,8,1],options);strong.endRetouch();}catch{rejected=true;}if(!rejected)throw Error('Out-of-selection blur accepted no-op');strong.redo();if(read(strong,16)[0]===255)throw Error('No-op blur destroyed redo');strong.undo();strong.beginRetouch([16,8,1],options);strong.cancelRetouch();if(read(strong,16)[0]!==255)throw Error('Blur cancel leaked pixels');}finally{weak.destroy();strong.destroy();edge.width=edge.height=0;}
}
